// Extrair dados da mensagem MQTT
const payload = msg.payload;

// Preparar dados para InfluxDB (formato line protocol)
const timestamp = Date.now() * 1000000; // nanoseconds

// Montar mensagem para InfluxDB
const sensores = payload.sensores || {};
const satelite = payload.satelite || {};

// Linha 1: sensores locais
msg.influx_telemetria = [
  {
    measurement: 'telemetria',
    tags: { device_id: payload.device_id || 'esp32-001' },
    fields: {
      temperatura:   sensores.temperatura   || 0,
      umidade_ar:    sensores.umidade_ar    || 0,
      umidade_solo:  sensores.umidade_solo  || 0,
      luminosidade:  sensores.luminosidade  || 0,
      chuva:         sensores.chuva         || 0
    },
    timestamp: new Date()
  }
];

// Linha 2: dados de satélite
msg.influx_satelite = [
  {
    measurement: 'satelite',
    tags: { device_id: payload.device_id || 'esp32-001' },
    fields: {
      ndvi:            satelite.ndvi           || 0,
      temp_superficie: satelite.temp_superficie || 0
    },
    timestamp: new Date()
  }
];

// Passar payload original
msg.payload_original = payload;

return msg;

const p = msg.payload_original;
const s = p.sensores || {};
const analise = p.analise || {};

const alertas = [];
let mensagem = '';

// Verificações de limites
if (s.temperatura >= 35) {
  alertas.push(`🌡️ CALOR CRÍTICO: ${s.temperatura}°C`);
}
if (s.temperatura <= 5) {
  alertas.push(`❄️ RISCO DE GEADA: ${s.temperatura}°C`);
}
if (analise.necessita_irrigacao) {
  alertas.push(`💧 IRRIGAR URGENTE: Solo ${s.umidade_solo}%`);
}
if (s.umidade_solo >= 85) {
  alertas.push(`🌊 SOLO ENCHARCADO: ${s.umidade_solo}%`);
}
if (s.umidade_ar <= 20) {
  alertas.push(`🏜️ AR MUITO SECO: ${s.umidade_ar}%`);
}

if (alertas.length > 0) {
  mensagem = `🚨 *AGROSAT ALERTA*\n`;
  mensagem += `📡 Device: ${p.device_id}\n`;
  mensagem += `⏰ ${new Date().toLocaleString('pt-BR')}\n\n`;
  mensagem += alertas.join('\n');
  mensagem += `\n\n📊 Status: ${p.status || 'ALERTA'}`;

  msg.payload = { text: mensagem };
  msg.alerta = true;
  return msg;
}

return null; // não enviar se não houver alertas

// Configure com seu Token e Chat ID do Telegram
// Substitua BOT_TOKEN e CHAT_ID abaixo
const BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN || 'SEU_TOKEN_AQUI';
const CHAT_ID   = process.env.TELEGRAM_CHAT_ID   || 'SEU_CHAT_ID_AQUI';

if (BOT_TOKEN === 'SEU_TOKEN_AQUI') {
  node.warn('Configure TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID nas variáveis de ambiente!');
  return null;
}

msg.url = `https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({
  chat_id: CHAT_ID,
  text: msg.payload.text,
  parse_mode: 'Markdown'
});

return msg;

const p = msg.payload;
msg.payload = [
  {
    measurement: 'alertas',
    tags: { device_id: p.device_id || 'esp32-001', nivel: p.nivel || 'INFO' },
    fields: { mensagem: p.alertas || '', timestamp_device: p.timestamp || 0 },
    timestamp: new Date()
  }
];
return msg;
